        return 0;
    }
    // Try a character that is definitely not in password? We don't know.
    // But we can try multiple characters to find the length.
    int d_test = query("b");
    if (d_test == 0) {
        printf("b\n");
        fflush(stdout);
        return 0;
    }
    // If both 'a' and 'b' are not in password, then d_first = d_test = length.
    // If one is in password, the distance will be length-1.
    // So the maximum of d_first and d_test is likely the length.
    length = (d_first > d_test) ? d_first : d_test;
    // But if both are in password, then both are length-1, so length = d_first+1.
    // We need to check if length could be d_first+1. We'll verify by sending a string 
    // of length d_first+1 of 'a's and see if distance is 0? No.
    // Actually we can send a string of length length of 'a's. If distance is 0, done.
    // If distance is > 0, then length is correct (if password has no 'a') or we need to adjust.

    // Let's just try to determine length by sending a string of length L_max of 'a's 
    // and then using the distance to compute length? Not reliable.

    // I'll use a different method: determine length by sending a string of all 'a's 
    // of length 1, then 2, ... until the distance equals 0 or we find the minimum.
    // The length is the l that gives the minimum distance (since distance = |l - len| + mismatches,
    // and mismatches is minimized when l = len if password contains many 'a's, otherwise 
    // distance is constant for l <= len if no 'a's). So we find l where distance is minimal.
    // Then we know len is either that l or close.

    int min_dist = MAX_L + 1;
    int best_len = 1;
    for (int l = 1; l <= MAX_L; l++) {
        char *s = malloc(l + 1);
        memset(s, 'a', l);
        s[l] = '\0';
        int d = query(s);
        if (d == 0) {
            printf("%s\n", s);
            fflush(stdout);
            free(s);
            return 0;
        }
        if (d < min_dist) {
            min_dist = d;
            best_len = l;
        }
        free(s);
    }
    // Now best_len is a candidate for length. We'll verify by sending a string of 
    // length best_len of 'a's and then of length best_len+1. If distance decreases, 
    // then length > best_len. If increases, length <= best_len.
    // We'll do a binary search to find exact length.

    int lo_len = 1, hi_len = MAX_L;
    while (lo_len < hi_len) {
        int mid = (lo_len + hi_len) / 2;
        char *s = malloc(mid + 1);
        memset(s, 'a', mid);
        s[mid] = '\0';
        int d_mid = query(s);
        if (d_mid == 0) {
            printf("%s\n", s);
            fflush(stdout);
            free(s);
            return 0;
        }
        // Compare with mid+1
        char *s2 = malloc((mid+1) + 1);
        memset(s2, 'a', mid+1);
        s2[mid+1] = '\0';
        int d_mid1 = query(s2);
        if (d_mid1 == 0) {
            printf("%s\n", s2);
            fflush(stdout);
            free(s2);
            free(s);
            return 0;
        }
        if (d_mid1 > d_mid) {
            // distance increased, so length <= mid
            hi_len = mid;
        } else if (d_mid1 < d_mid) {
            // distance decreased, so length > mid
            lo_len = mid + 1;
        } else {
            // equal, could be that length > mid+1 or something; we'll assume length > mid
            lo_len = mid + 1;
        }
        free(s);
        free(s2);
    }
    length = lo_len;

    // Now we know the exact length. Build the password character by character.
    char password[MAX_L + 1];
    password[length] = '\0';
    // Start with a base string of all 'a's of correct length
    char base[MAX_L + 1];
    memset(base, 'a', length);
    base[length] = '\0';
    int base_dist = query(base);
    if (base_dist == 0) {
        printf("%s\n", base);
        fflush(stdout);
        return 0;
    }

    // For each position, try all possible characters (a-z, A-Z, 0-9) to see which one reduces distance
    char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (int i = 0; i < length; i++) {
        for (int c = 0; c < 62; c++) {
            char test[MAX_L + 1];
            strcpy(test, base);
            test[i] = charset[c];
            int d = query(test);
            if (d == 0) {
                printf("%s\n", test);
                fflush(stdout);
                return 0;
            }
            if (d < base_dist) {
                // This character is better
                base[i] = charset[c];
                base_dist = d;
                break; // found the correct character for this position
            }
        }
    }

    // If we haven't found the password yet, output the base
    printf("%s\n", base);
    fflush(stdout);

    return 0;
}

